package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="insurance_claims") public class InsuranceClaim { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="patient_id",nullable=false) private User patient; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="appointment_id") private Appointment appointment; @Column(length=120) private String provider; @Column(length=100) private String policyNumber; @Column(precision=12,scale=2) private BigDecimal amount=BigDecimal.ZERO; @Column(length=30) private String status="SUBMITTED"; @Column(columnDefinition="TEXT") private String notes; private LocalDateTime createdAt; @PrePersist void c(){createdAt=LocalDateTime.now();} public InsuranceClaim(){} public InsuranceClaim(User p,Appointment a,String provider,String policy,BigDecimal amount,String notes){patient=p;appointment=a;this.provider=provider;policyNumber=policy;this.amount=amount;this.notes=notes;} public Long getId(){return id;} public User getPatient(){return patient;} public Appointment getAppointment(){return appointment;} public String getProvider(){return provider;} public String getPolicyNumber(){return policyNumber;} public BigDecimal getAmount(){return amount;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getNotes(){return notes;} public LocalDateTime getCreatedAt(){return createdAt;} }
